inline Integer power(unsigned long base, unsigned long exponent) {
    Integer result; mpz_ui_pow_ui(result.get_mpz_t(), base, exponent); return result;
}
inline Rational local_density(const Density& d, unsigned long v, unsigned long unit) {
    if (v<d.content_exponent) return Rational();
    v-=d.content_exponent;
    const auto& c=constants(); Rational result;
    if (d.kind==1) {
        const int chi=d.prime==2 ? 1 : kronecker(static_cast<long>((unit%d.prime)*d.unit_inverse%d.prime),d.prime);
        const Rational ratio=make_rational(Integer(1),power(d.prime,(d.rank/2-1)*v));
        Rational signed_ratio=ratio; if (v%2) signed_ratio=-signed_ratio;
        result=c[density_values[d.begin]]
            +(c[density_values[d.begin+1]]+chi*c[density_values[d.begin+3]])*ratio
            +(c[density_values[d.begin+2]]+chi*c[density_values[d.begin+4]])*signed_ratio;
    } else {
        const unsigned long modulus=power(d.prime,d.threshold).get_ui();
        unit=(unit%modulus)*d.unit_inverse%modulus;
        Rational factor(1); const Integer denominator=power(d.prime,d.rank-2);
        for (unsigned long j=0;j<=v/2;++j) {
            const unsigned long exponent=v-2*j;
            const unsigned long residue=exponent>=d.threshold ? 0 : power(d.prime,exponent).get_ui()*unit%modulus;
            if (residue>=d.count) fail("IPR real density table is incomplete");
            result+=factor*c[density_values[d.begin+residue]];
            factor/=denominator;
        }
    }
    return result*power(d.prime,d.content_exponent);
}

inline void multiply_density(Rational& denominator, int id, const Integer& argument) {
    if (id < 0 || argument <= 0) fail("invalid IPR local density argument");
    const Density& d = densities[id];
    Integer unit;
    const Integer prime(d.prime);
    const auto valuation = mpz_remove(unit.get_mpz_t(), argument.get_mpz_t(), prime.get_mpz_t());
    // Only the unit modulo the fixed local modulus enters the coefficient.
    const unsigned long modulus = d.kind == 1 ? d.prime : power(d.prime,d.threshold).get_ui();
    denominator *= local_density(d, valuation, residue(unit, modulus));
}
inline Rational base_value(std::size_t identifier,const Integer& index) {
    const auto& base=bases[identifier]; if (!index) fail("IPR real base index must be positive");
    if (index%base.content != 0) return Rational();
    const auto& c=constants(); Rational result;
    for (std::size_t i=base.begin;i<base.begin+base.count;++i) {
        const auto& term=kernels[i]; if (index%term.denominator != 0) continue;
        const Integer n=(index/term.denominator)*term.numerator;
        if (term.parity>=0) {
            unsigned long v=0; Integer unit=index;
            while (unit%2==0) { unit/=2; ++v; }
            if (static_cast<int>(v%2)!=term.parity || static_cast<int>(residue(unit,8))!=term.unit) continue;
        }
        Rational value;
        switch (term.kind) {
        case 0: value=Rational(two_character_sum(term.weight,term.left,term.right,n)); break;
        case 1: value=cohen_number(term.weight,n)*kronecker(term.twist,n); break;
        case 2: value=hurwitz_class_number(n); break;
        case 3: value=Rational(two_character_sum(0,term.left,term.right,n)); break;
        case 4: { const Integer root=integer_square_root(n); value=Rational(root*root==n ? 1 : 0); break; }
        default: fail("unknown IPR real arithmetic kernel");
        }
        result+=c[term.coefficient]*value;
    }
    return result;
}
inline Rational normalized_base(const ExpressionRow& row, const Integer& n) {
    Rational value = base_value(row.function, n);
    if (value == 0 || row.density_mask == 0) return value;
    const Base& base = bases[row.function];
    Rational denominator(1);
    if (row.density_mask & 1U) multiply_density(denominator,base.two, n);
    if (row.density_mask & 2U) multiply_density(denominator,base.three, n);
    if (denominator <= 0) fail("nonzero IPR real mass has a zero density denominator");
    value /= denominator;
    return value;
}

template<std::size_t N> inline Rational evaluate(const std::array<ExpressionRow,N>& rows,const Integer& m) {
    if (!m) fail("IPR real index must be positive");
    const auto& c=constants(); Rational total;
    for (const auto& row:rows) {
        const Rational& coefficient=c[row.coefficient[residue(m,4)]]; if (coefficient==0) continue;
        const Integer n=m*row.scale+row.intercept;
        const Rational value = normalized_base(row, n);
        if (value != 0) total += coefficient * value;
    }
    return total;
}
inline Rational negative_split(const Integer& m) {
    return evaluate(split_rows,m);
}

inline Rational negative_antipodal(const Integer& m) {
    return evaluate(antipodal_rows,m);
}
